import '@servicenow/sdk/global'
import { BooleanColumn, DateTimeColumn, IntegerColumn, StringColumn } from '@servicenow/sdk/core'
import { Flow, FlowArray, FlowObject, trigger, wfa } from '@servicenow/sdk/automation'

/**
 * Test flow for setFlowVariables with FlowArray
 * Tests that plain array literals can be assigned to FlowArray flow variables
 */
export const setFlowVariablesFlowArrayTest = Flow(
    {
        $id: Now.ID['set-flow-variables-flow-array-test'],
        name: 'SetFlowVariables FlowArray Test',
        description: 'Test setFlowVariables with FlowArray values',
        flowPriority: 'MEDIUM',
        runAs: 'system',
        runWithRoles: [],
        flowVariables: {
            // FlowArray with FlowObject elements (top-level)
            users: FlowArray({
                label: 'Users',
                mandatory: false,
                elementType: FlowObject({
                    fields: {
                        name: StringColumn({ label: 'Name', mandatory: false }),
                        id: IntegerColumn({ label: 'ID', mandatory: false }),
                    },
                    label: 'User',
                    mandatory: false,
                }),
                childName: 'user',
            }),

            // FlowArray with FlowObject elements (for tags)
            tags: FlowArray({
                label: 'Tags',
                mandatory: false,
                elementType: FlowObject({
                    fields: {
                        value: StringColumn({ label: 'Tag Value', mandatory: false }),
                    },
                    label: 'Tag',
                    mandatory: false,
                }),
                childName: 'tag',
            }),

            // FlowArray with primitive string elements
            tagList: FlowArray({
                label: 'Tag List',
                mandatory: false,
                elementType: StringColumn({ label: 'Tag Item', mandatory: false }),
                childName: 'tagItem',
            }),

            // FlowArray with primitive integer elements
            scores: FlowArray({
                label: 'Scores',
                mandatory: false,
                elementType: IntegerColumn({ label: 'Score', mandatory: false }),
                childName: 'score',
            }),

            // FlowArray with primitive boolean elements
            flags: FlowArray({
                label: 'Flags',
                mandatory: false,
                elementType: BooleanColumn({ label: 'Flag', mandatory: false }),
                childName: 'flag',
            }),

            // FlowArray with primitive datetime elements
            timestamps: FlowArray({
                label: 'Timestamps',
                mandatory: false,
                elementType: DateTimeColumn({ label: 'Timestamp', mandatory: false }),
                childName: 'timestamp',
            }),

            // FlowObject with nested primitive FlowArrays (like example dataCollection)
            dataCollection: FlowObject({
                fields: {
                    title: StringColumn({ label: 'Title', mandatory: false }),
                    stringList: FlowArray({
                        label: 'String List',
                        mandatory: false,
                        elementType: StringColumn({ label: 'String Item', mandatory: false }),
                        childName: 'stringItem',
                    }),
                    numberList: FlowArray({
                        label: 'Number List',
                        mandatory: false,
                        elementType: IntegerColumn({ label: 'Number Item', mandatory: false }),
                        childName: 'numberItem',
                    }),
                    booleanList: FlowArray({
                        label: 'Boolean List',
                        mandatory: false,
                        elementType: BooleanColumn({ label: 'Boolean Item', mandatory: false }),
                        childName: 'booleanItem',
                    }),
                    dateList: FlowArray({
                        label: 'Date List',
                        mandatory: false,
                        elementType: DateTimeColumn({ label: 'Date Item', mandatory: false }),
                        childName: 'dateItem',
                    }),
                },
                label: 'Data Collection',
                mandatory: false,
            }),
        },
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['set-flow-vars-flow-array-trigger'] },
        {
            table: 'incident',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
        }
    ),
    (params) => {
        // Test 1: FlowArray with FlowObject elements - plain object literals
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['set-flow-vars-object-array'],
                annotation: 'Object array literals',
            },
            params.flowVariables,
            {
                users: [
                    { name: 'Alice', id: 1 },
                    { name: 'Bob', id: 2 },
                    { name: 'Charlie', id: 3 },
                ],
            }
        )

        // Test 2: FlowArray with wrapped string values
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['set-flow-vars-wrapped-strings'],
                annotation: 'Wrapped string array',
            },
            params.flowVariables,
            {
                tags: [{ value: 'urgent' }, { value: 'critical' }, { value: 'p1' }],
            }
        )

        // Test 3: FlowArray with datapills in objects
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['set-flow-vars-array-datapills'],
                annotation: 'Array with datapills',
            },
            params.flowVariables,
            {
                tags: [{ value: 'static' }, { value: wfa.dataPill(params.trigger.current.number, 'string') }],
            }
        )

        // Test 4: Empty FlowArray
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['set-flow-vars-empty-array'],
                annotation: 'Empty array',
            },
            params.flowVariables,
            {
                tags: [],
            }
        )

        // Test 5: Primitive string array literals
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['set-flow-vars-primitive-string-array'],
                annotation: 'Primitive string array',
            },
            params.flowVariables,
            {
                tagList: ['urgent', 'critical', 'high-priority'],
            }
        )

        // Test 6: Primitive integer array literals
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['set-flow-vars-primitive-integer-array'],
                annotation: 'Primitive integer array',
            },
            params.flowVariables,
            {
                scores: [100, 95, 88, 76],
            }
        )

        // Test 7: Primitive array with datapills
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['set-flow-vars-primitive-array-datapills'],
                annotation: 'Primitive array with datapills',
            },
            params.flowVariables,
            {
                tagList: ['static-tag', wfa.dataPill(params.trigger.current.number, 'string')],
            }
        )

        // Test 8: Empty primitive array
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['set-flow-vars-empty-primitive-array'],
                annotation: 'Empty primitive array',
            },
            params.flowVariables,
            {
                scores: [],
            }
        )

        // Test 9: Primitive boolean array
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['set-flow-vars-boolean-array'],
                annotation: 'Boolean array',
            },
            params.flowVariables,
            {
                flags: [true, false, true, false],
            }
        )

        // Test 10: Primitive datetime array
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['set-flow-vars-datetime-array'],
                annotation: 'Datetime array',
            },
            params.flowVariables,
            {
                timestamps: ['2024-01-01 10:00:00', '2024-06-15 14:30:00', '2024-12-31 23:59:59'],
            }
        )

        // Test 11: FlowObject with nested primitive arrays (comprehensive)
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['set-flow-vars-nested-primitive-arrays'],
                annotation: 'Nested primitive arrays',
            },
            params.flowVariables,
            {
                dataCollection: {
                    title: 'Sample Collection',
                    stringList: ['apple', 'banana', 'cherry'],
                    numberList: [10, 20, 30, 40],
                    booleanList: [true, false, true],
                    dateList: ['2024-01-15 09:00:00', '2024-02-20 15:30:00'],
                },
            }
        )

        // Test 12: FlowObject with nested arrays and datapills
        wfa.flowLogic.setFlowVariables(
            {
                $id: Now.ID['set-flow-vars-nested-arrays-datapills'],
                annotation: 'Nested arrays with datapills',
            },
            params.flowVariables,
            {
                dataCollection: {
                    title: wfa.dataPill(params.trigger.current.short_description, 'string'),
                    stringList: ['static', wfa.dataPill(params.trigger.current.number, 'string')],
                    numberList: [100, wfa.dataPill(params.trigger.current.priority, 'integer')],
                    booleanList: [true, wfa.dataPill(params.trigger.current.active, 'boolean')],
                    dateList: ['2024-01-01 00:00:00'],
                },
            }
        )
    }
)
